function formatListingLocation(item) {
  if (!item) return "Meghalaya";
  if (item.location && typeof item.location === "object" && item.location.name && item.location.name !== "Unknown") {
    return item.location.name;
  }
  if (typeof item.location === "string" && item.location.trim() && item.location !== "Unknown") {
    return item.location.trim();
  }
  if (item.location_name && typeof item.location_name === "string" && item.location_name.trim() && item.location_name !== "Unknown") {
    return item.location_name.trim();
  }
  const parts = [item.town || item.village, item.district, item.state].filter(Boolean);
  if (parts.length > 0) return parts.join(", ");
  return "Tura, Meghalaya";
}

