async function sendNotification(userId, title, message, type) {
  if (!userId) return;
  const notifType = type || "system";
  const nowIso = new Date().toISOString();
  const notifObj = {
    id: "notif_" + Date.now() + "_" + Math.random().toString(36).slice(2, 7),
    user_id: userId,
    title: title,
    message: message,
    type: notifType,
    read_at: null,
    created_at: nowIso
  };
  try {
    const isUuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
    if (isUuid.test(userId)) {
      await L.from("notifications").insert({
        user_id: userId,
        title: title,
        message: message,
        type: notifType,
        read_at: null
      });
    }
  } catch(err) {}
  try {
    const saved = JSON.parse(localStorage.getItem("user_notifications_" + userId) || "[]");
    const isDuplicate = saved.some(function(n) {
      return n.title === title && (Date.now() - new Date(n.created_at).getTime()) < 3600000;
    });
    if (!isDuplicate) {
      saved.unshift(notifObj);
      localStorage.setItem("user_notifications_" + userId, JSON.stringify(saved));
    }
  } catch(err) {}
  try {
    if (typeof window !== "undefined") {
      window.dispatchEvent(new CustomEvent("notification_received", { detail: notifObj }));
    }
  } catch(err) {}
}

async function checkProExpiryNotifications(user, profile) {
  if (!user || !profile) return;
  try {
    let expDate = profile.pro_expires_at || profile.pro_expiry_at || profile.approved_expiry_date;
    if (!expDate && user.id) {
      try {
        const list = JSON.parse(localStorage.getItem("all_recharge_requests") || "[]");
        const approved = list.find(function(r) { return r.user_id === user.id && r.status === "approved"; });
        if (approved) {
          if (approved.approved_expiry_date) expDate = approved.approved_expiry_date;
          else if (approved.submitted_at) {
            const days = (approved.plan && approved.plan.duration_days) ? approved.plan.duration_days : 30;
            expDate = new Date(new Date(approved.submitted_at).getTime() + days * 86400000).toISOString();
          }
        }
      } catch(e) {}
    }
    if (!expDate) return;
    const expMs = new Date(expDate).getTime();
    if (isNaN(expMs)) return;
    const now = Date.now();
    const diffMs = expMs - now;
    const daysLeft = Math.ceil(diffMs / 86400000);
    const todayStr = new Date().toISOString().slice(0, 10);

    // 1) 3 Days or less before expiry: Send 2 times a day
    if (diffMs > 0 && daysLeft <= 3) {
      const storageKey = "pro_expiry_reminders_" + user.id + "_" + todayStr;
      let sentTimestamps = [];
      try { sentTimestamps = JSON.parse(localStorage.getItem(storageKey) || "[]"); } catch(e) {}
      const shouldSend = (sentTimestamps.length === 0) || (sentTimestamps.length === 1 && (now - sentTimestamps[0]) >= 4 * 3600 * 1000);
      if (shouldSend) {
        const daysText = daysLeft === 0 ? "Today" : (daysLeft === 1 ? "1 Day" : daysLeft + " Days");
        const title = "⚠️ PRO Plan Expiring in " + daysText + "!";
        const message = "Aapka PRO Membership plan " + (daysLeft <= 1 ? "jaldi khatam hone wala hai" : daysLeft + " din mein khatam hone wala hai") + ". Top PRO placement aur badge continue rakhne ke liye abhi renew karein.";
        await sendNotification(user.id, title, message, "pro_expiring_soon");
        sentTimestamps.push(now);
        localStorage.setItem(storageKey, JSON.stringify(sentTimestamps));
      }
    }
    // 2) Plan Expired: Send 2 times a day
    else if (diffMs <= 0) {
      const storageKey = "pro_expired_reminders_" + user.id + "_" + todayStr;
      let sentTimestamps = [];
      try { sentTimestamps = JSON.parse(localStorage.getItem(storageKey) || "[]"); } catch(e) {}
      const shouldSend = (sentTimestamps.length === 0) || (sentTimestamps.length === 1 && (now - sentTimestamps[0]) >= 4 * 3600 * 1000);
      if (shouldSend) {
        const title = "👑 PRO Membership Expired";
        const message = "Aapka PRO Membership plan khatam ho gaya hai. Dobara PRO badge aur priority features activate karne ke liye Profile ya Recharge page se renew karein.";
        await sendNotification(user.id, title, message, "pro_expired");
        sentTimestamps.push(now);
        localStorage.setItem(storageKey, JSON.stringify(sentTimestamps));
      }
    }
  } catch(err) {
    console.warn("checkProExpiryNotifications error:", err);
  }
}
